import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
const [packagePath,artifactPath]=process.argv.slice(1);
const bundled=createRequire('/Users/tsm0420/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/package.json');
const markedPath=bundled.resolve('marked');
const {marked}=await import(markedPath);
const consumer=createRequire(packagePath+'/package.json');
const {load}=consumer('cheerio');
const cheerioPath=consumer.resolve('cheerio');
const renderer={
 marked:{entry:markedPath,version:JSON.parse(await readFile(markedPath.replace(/lib\/marked\.esm\.js$/,'package.json'),'utf8')).version,sha256:createHash('sha256').update(await readFile(markedPath)).digest('hex')},
 cheerio:{entry:cheerioPath,version:JSON.parse(await readFile(consumer.resolve('cheerio/package.json'),'utf8')).version,sha256:createHash('sha256').update(await readFile(cheerioPath)).digest('hex')},
 options:{gfm:true},scope:'Local parser conversion/DOM inspection only; entry-file digests, no native browser claim.'
};
await writeFile(artifactPath+'/renderer-identity.json',JSON.stringify(renderer,null,2)+'\n');
const rows=[];
for(const kind of ['audit','aso','plan','visibility','compare']){
 const doc=JSON.parse(await readFile(artifactPath+'/report-'+kind+'.json','utf8'));
 const md=await readFile(artifactPath+'/report-'+kind+'.md','utf8');
 const html=await marked.parse(md,{gfm:true});
 const $=load(html);
 const table=$('table tbody tr').map((_i,row)=>[$(row).find('td').map((_j,cell)=>$(cell).text()).get()]).get();
 assert.equal(table.length,doc.findings.length);
 assert.deepEqual(table.map(row=>row[1]),doc.findings.map(row=>row.status));
 if(kind==='plan')assert.equal(table[0][0],'first second|<&>');
 if(kind==='compare')assert.equal(table[0][0],'finding:first second|<&>');
 await writeFile(artifactPath+'/report-'+kind+'.html',html);
 rows.push({kind,table});
}
await writeFile(artifactPath+'/rendered-rows.json',JSON.stringify(rows,null,2)+'\n');
console.log('All five installed report tables retain exact finding row/status counts; CRLF ID displays as one space. Local parser only.');
